const replaceGroupOwners = `-- name: ReplaceGroupOwners :exec
WITH gone AS (
    DELETE FROM staff.group_owners
    WHERE group_id = $1 AND NOT (person_id = ANY($2::bigint[]))
)
INSERT INTO staff.group_owners (group_id, person_id)
SELECT $1::bigint, unnest($2::bigint[])
ON CONFLICT (group_id, person_id) DO NOTHING
`

type ReplaceGroupOwnersParams struct {
	GroupID   int64
	PersonIds []int64
}

// ReplaceGroupOwners makes a group's owners exactly @person_ids: the others
// deleted, the missing added, in one statement.
func (q *Queries) ReplaceGroupOwners(ctx context.Context, arg ReplaceGroupOwnersParams) error {
	_, err := q.db.Exec(ctx, replaceGroupOwners, arg.GroupID, arg.PersonIds)
	return err
}

