const upsertGroupTrait = `-- name: UpsertGroupTrait :one
INSERT INTO staff.group_traits (group_id, provider, values, enabled, state, attempts, next_attempt_at)
VALUES ($1, $2, $3::jsonb, true, 'pending', 0, $4::timestamptz)
ON CONFLICT (group_id, provider) DO UPDATE SET
    values = EXCLUDED.values,
    enabled = true,
    disabled_at = NULL,
    state = 'pending',
    last_values_hash = NULL,
    last_error = NULL,
    last_error_field = NULL,
    retired_at = NULL,
    attempts = 0,
    next_attempt_at = EXCLUDED.next_attempt_at,
    lease_id = NULL,
    lease_until = NULL
RETURNING group_id, provider, values, enabled, disabled_at, external_id, state, last_values_hash, last_members_hash, last_error, last_error_field, synced_at, retired_at, attempts, next_attempt_at, lease_id, lease_until
`

type UpsertGroupTraitParams struct {
	GroupID  int64
	Provider string
	Values   []byte
	Now      time.Time
}

// UpsertGroupTrait turns @provider on for a group with @values: the section
// pending, no attempt counted, due now, the values' hash forgotten — so the
// worker's next cycle sends them — and no longer disabled, retired or
// failing. The external group's id and the members' hash stay: the provider
// finds its group again by the caller's id. A claim the worker holds on the
// row is ended, so its result, judged on the values it read, is never
// written over these (WriteGroupTraitResult).
func (q *Queries) UpsertGroupTrait(ctx context.Context, arg UpsertGroupTraitParams) (StaffGroupTrait, error) {
	row := q.db.QueryRow(ctx, upsertGroupTrait,
		arg.GroupID,
		arg.Provider,
		arg.Values,
		arg.Now,
	)
	var i StaffGroupTrait
	err := row.Scan(
		&i.GroupID,
		&i.Provider,
		&i.Values,
		&i.Enabled,
		&i.DisabledAt,
		&i.ExternalID,
		&i.State,
		&i.LastValuesHash,
		&i.LastMembersHash,
		&i.LastError,
		&i.LastErrorField,
		&i.SyncedAt,
		&i.RetiredAt,
		&i.Attempts,
		&i.NextAttemptAt,
		&i.LeaseID,
		&i.LeaseUntil,
	)
	return i, err
}

const writeGroupTraitResult = `-- name: WriteGroupTraitResult :execrows
UPDATE staff.group_traits SET
    external_id = $1::varchar,
    state = $2,
    last_values_hash = $3::bytea,
    last_members_hash = $4::bytea,
    last_error = $5::varchar,
    last_error_field = $6::varchar,
    synced_at = $7::timestamptz,
    retired_at = $8::timestamptz,
    attempts = $9,
    next_attempt_at = $10::timestamptz,
    lease_id = NULL,
    lease_until = NULL
WHERE group_id = $11 AND provider = $12 AND lease_id = $13::uuid
`

type WriteGroupTraitResultParams struct {
	ExternalID      *string
	State           string
	LastValuesHash  []byte
	LastMembersHash []byte
	LastError       *string
	LastErrorField  *string
	SyncedAt        *time.Time
	RetiredAt       *time.Time
	Attempts        int32
	NextAttemptAt   *time.Time
	GroupID         int64
	Provider        string
	LeaseID         uuid.UUID
}

// WriteGroupTraitResult records what a claim did on a section, every sync
// column replaced, and clears the lease — on the claim's lease alone: no
// row is a section gone (the group deleted) or a claim lost, its lease
// lapsed and taken by another cycle or ended by HR's change of the section
// (UpsertGroupTrait, DisableGroupTrait). The values and the switch are HR's
// and never written here.
func (q *Queries) WriteGroupTraitResult(ctx context.Context, arg WriteGroupTraitResultParams) (int64, error) {
	result, err := q.db.Exec(ctx, writeGroupTraitResult,
		arg.ExternalID,
		arg.State,
		arg.LastValuesHash,
		arg.LastMembersHash,
		arg.LastError,
		arg.LastErrorField,
		arg.SyncedAt,
		arg.RetiredAt,
		arg.Attempts,
		arg.NextAttemptAt,
		arg.GroupID,
		arg.Provider,
		arg.LeaseID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
